package com.example.domain.model.i18n

internal object DuaIt1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Al risveglio", "Lode ad Allah che ci ha fatto rivivere dopo averci fatto morire (dormire), e a Lui è il ritorno.", "Recitata appena svegli, in ringraziamento ad Allah.", "Il Profeta ﷺ la recitava al risveglio — iniziare la giornata con gratitudine e memoria dell'aldilà."),
        "dua_leaving_home" to DuaText("Uscendo di casa", "Nel nome di Allah, mi affido ad Allah, non c'è forza né potenza se non in Allah.", "Recitata uscendo di casa per cercare protezione.", "A chi la recita si dice: sei stato guidato, sei stato bastato, sei stato protetto — e Satana si allontana da lui."),
        "dua_anxiety_distress" to DuaText("Supplica per ansia e tristezza", "O Allah, mi rifugio in Te dall'ansia e dalla tristezza, dalla debolezza e dalla pigrizia, dall'avarizia e dalla vigliaccheria, dal peso dei debiti e dalla prepotenza altrui.", "Nei momenti di ansia, tristezza, debiti e sofferenza interiore.", "Il Profeta ﷺ recitava spesso questa supplica per rifugiarsi da tristezza, pigrizia e debiti."),
        "dua_sayyidul_istighfar" to DuaText("Il signore del pentimento (Sayyidul Istighfar)", "O Allah, Tu sei il mio Signore, non c'è divinità se non Te. Tu mi hai creato e io sono Tuo servo. Rimango fedele al Tuo patto e alla Tua promessa finché posso. Mi rifugio in Te dal male che ho commesso. Riconosco la Tua grazia su di me e riconosco il mio peccato: perdonami, poiché nessuno perdona i peccati se non Te.", "Recitata mattina e sera — la migliore supplica di pentimento insegnata dal Profeta ﷺ.", "Chi la recita la sera con ferma fede e muore quella notte entra in Paradiso; lo stesso vale per chi la recita al mattino."),
        "dua_parents" to DuaText("Supplica per i genitori", "Signore mio, abbi misericordia di loro come essi mi hanno cresciuto quando ero piccolo.", "Supplica coranica in cambio delle cure ricevute dai genitori nell'infanzia.", "Allah ha ordinato questa supplica per i genitori direttamente nel Corano."),
        "dua_entering_mosque" to DuaText("Entrando in moschea", "O Allah, aprimi le porte della Tua misericordia.", "Recitata entrando in moschea con il piede destro.", "Il Profeta ﷺ insegnò questa supplica per entrare in moschea."),
        "dua_morning_asbahna" to DuaText("Invocazione del mattino", "Siamo giunti al mattino e con noi il regno appartiene ad Allah; la lode appartiene ad Allah; non c'è divinità se non Allah, Unico, senza associati; a Lui il regno, a Lui la lode, ed Egli è Onnipotente su ogni cosa.", "Invocazione sunnita recitata al mattino.", "Iniziare la giornata riconoscendo il dominio e l'unicità di Allah."),
        "dua_evening_amsayna" to DuaText("Invocazione della sera", "Siamo giunti alla sera e con noi il regno appartiene ad Allah; la lode appartiene ad Allah; non c'è divinità se non Allah, Unico, senza associati; a Lui il regno, a Lui la lode, ed Egli è Onnipotente su ogni cosa.", "Invocazione sunnita recitata alla sera.", "Iniziare la notte riconoscendo il dominio e l'unicità di Allah."),
        "dua_before_sleep" to DuaText("Prima di dormire", "Nel Tuo nome, o Allah, muoio e vivo.", "Recitata dopo essersi sdraiati per dormire.", "Il Profeta ﷺ la recitava prima di dormire."),
        "dua_travel" to DuaText("Supplica del viaggio", "Gloria a Colui che ci ha sottomesso questo, mentre noi non ne eravamo capaci; e invero al nostro Signore ritorneremo.", "Recitata salendo su un mezzo di trasporto dopo tre takbir.", "Supplica di viaggio raccomandata per protezione e benedizione."),
        "dua_ayatul_kursi" to DuaText("Ayat al-Kursi dopo la preghiera", "Allah, non c'è divinità se non Lui, il Vivente, l'Eterno Sostenitore. Non Lo coglie sonnolenza né sonno. A Lui appartiene tutto ciò che è nei cieli e sulla terra. Chi può intercedere presso di Lui senza il Suo permesso? Egli conosce ciò che sta davanti e dietro le creature. Esse non abbracciano nulla della Sua scienza se non ciò che Egli vuole. Il Suo Trono abbraccia i cieli e la terra, e non Gli costa fatica custodirli. Egli è l'Altissimo, il Sublime.", "Recitata dopo ogni preghiera obbligatoria e prima di dormire.", "Chi la recita dopo ogni preghiera obbligatoria, nulla gli impedisce di entrare in Paradiso se non la morte; chi la recita prima di dormire resta protetto fino al mattino."),
        "dua_hasbunallah" to DuaText("Allah ci basta", "Allah ci basta ed Egli è il miglior protettore.", "Recitata nella paura di un nemico o di un grande pericolo.", "La disse Abramo quando fu gettato nel fuoco, e il Profeta ﷺ nei momenti di pericolo."),
        "dua_entering_home" to DuaText("Entrando in casa", "Nel nome di Allah siamo entrati, nel nome di Allah siamo usciti, e al nostro Signore Allah ci affidiamo.", "Recitata entrando in casa, menzionando il nome di Allah e salutando.", "A chi ricorda Allah entrando in casa e mangiando, Satana dice: non c'è alloggio né cena per voi."),
        "dua_yunus" to DuaText("Supplica del profeta Giona (pace su di lui)", "Non c'è divinità se non Te, gloria a Te; in verità sono stato tra gli ingiusti.", "Supplica del profeta Giona nel ventre del pesce — per ogni difficoltà.", "Non c'è musulmano che la invochi in qualsiasi faccenda senza che Allah gli risponda."),
        "dua_karb" to DuaText("Supplica nella grave afflizione", "Non c'è divinità se non Allah, il Sublime, il Magnanimo. Non c'è divinità se non Allah, Signore del Trono immenso. Non c'è divinità se non Allah, Signore dei cieli, della terra e del nobile Trono.", "Recitata nella grave afflizione e angoscia.", "Il Profeta ﷺ la recitava nei momenti di afflizione."),
    )
